17	     *
18	     * @param code the customer code; non-digit characters are ignored
19	     * @return the Luhn check digit, between 0 and 9 inclusive
20	     */
21	    public static int checkDigit(String code) {
22	        int sum = 0;
23	        boolean dbl = true;
24	        for (int i = code.length() - 1; i >= 0; i--) {
25	            char c = code.charAt(i);
26	            if (c < '0' || c > '9') {
27	                continue;
28	            }
29	            int d = c - '0';
30	            if (dbl) {
31	                d *= 2;
32	                if (d > 9) {
33	                    d -= 9;
34	                }
35	            }
36	            sum += d;
37	            dbl = !dbl;
38	        }
39	        return (10 - (sum % 10)) % 10;
40	    }
