1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Single source of truth for an owner's {@code identityKey}: the one derived value all duplicate
7	 * detection on {@code POST /api/owners} is expressed through, and the {@code identityKey} field the
8	 * owner response carries. The key is
9	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}; two owners are the same
10	 * identity exactly when their whole keys are equal.
11	 *
12	 * <p>This is a model-level derivation of an {@link Owner} (like {@link MembershipLevel}): it is
13	 * consumed both by the response mapper and by the create pipeline's identity check, so it lives in the
14	 * model layer rather than beside the pipeline functions.
15	 *
16	 * <p>It deliberately folds the former separate telephone, email and household duplicate checks into
17	 * one comparison. Because the telephone is part of the key, two members of the same household (same
18	 * {@code householdId}) with different telephones have different keys and are both allowed — only an
19	 * exact full-key match is a duplicate.
20	 *
21	 * <p>The components are normalized the same way for a submitted owner and a stored one, so values with
22	 * incidental telephone formatting or email casing still match: the telephone is run through
23	 * {@link OwnerTelephone#toE164(String)} and the email is lower-cased. A {@code null} component
24	 * contributes the empty string.
25	 */
26	public final class OwnerIdentity {
27	
28	    private OwnerIdentity() {
29	    }
30	
31	    /** The {@code identityKey} of a persisted or in-flight owner, computed from its stored fields. */
32	    public static String of(Owner owner) {
33	        String normalizedTelephone = OwnerTelephone.toE164(owner.getTelephone());
34	        if (normalizedTelephone == null) {
35	            normalizedTelephone = owner.getTelephone() == null ? "" : owner.getTelephone();
36	        }
37	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
38	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
39	        return normalizedTelephone + "|" + email + "|" + householdId;
40	    }
41	}
