1	package org.springframework.samples.petclinic.model;
2	
3	/**
4	 * Single source of truth for the "E.164 telephone" concept: the validating step converts a submitted
5	 * value to E.164 before it is stored, and the derived {@link OwnerIdentity} normalizes stored values
6	 * the same way when forming an owner's identity key. Keeping the rule here ensures the value that gets
7	 * stored and the value compared for identity can never silently diverge.
8	 */
9	public final class OwnerTelephone {
10	
11	    private OwnerTelephone() {
12	    }
13	
14	    /**
15	     * Convert a raw telephone to E.164 form, or return {@code null} if it cannot form a valid E.164
16	     * number. Spaces, dashes and brackets are stripped. A leading {@code '+'} keeps its country code;
17	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from
18	     * the national digits. The result must have 8 to 15 digits after the {@code '+'}.
19	     *
20	     * <p>The national-number length is also checked against the country code: {@code '+61'} (Australia)
21	     * requires 9 national digits and {@code '+1'} (NANP) requires 10. A number whose national part is
22	     * the wrong length for its country code cannot form a valid E.164 number and returns {@code null}.
23	     */
24	    public static String toE164(String value) {
25	        if (value == null) {
26	            return null;
27	        }
28	        // Strip spaces, dashes and brackets (round and square).
29	        String cleaned = value.replaceAll("[\\s()\\[\\]-]", "");
30	        String digits;
31	        if (cleaned.startsWith("+")) {
32	            digits = cleaned.substring(1);
33	        }
34	        else {
35	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
36	            digits = "61" + national;
37	        }
38	        if (!digits.matches("[0-9]{8,15}")) {
39	            return null;
40	        }
41	        if (!nationalLengthValid(digits)) {
42	            return null;
43	        }
44	        return "+" + digits;
45	    }
46	
47	    /**
48	     * Check the national-number length for the known country codes. {@code '+61'} requires 9 national
49	     * digits and {@code '+1'} requires 10; other country codes are not length-checked here.
50	     */
51	    private static boolean nationalLengthValid(String digits) {
52	        if (digits.startsWith("61")) {
53	            return digits.length() - 2 == 9;
54	        }
55	        if (digits.startsWith("1")) {
56	            return digits.length() - 1 == 10;
57	        }
58	        return true;
59	    }
60	}
61

1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * City-to-region lookup backing the {@code locality} field produced by
7	 * {@link OwnerMapper#toOwnerDto}. The table pins each known city to its canonical region string; any
8	 * city not listed derives the locality {@code "UNKNOWN"}.
9	 */
10	public final class Regions {
11	
12	    /** City -> canonical region. Anything not listed derives locality {@link #UNKNOWN}. */
13	    private static final Map<String, String> CITY_REGION = Map.of(
14	        "Sydney", "NSW",
15	        "Melbourne", "VIC",
16	        "Brisbane", "QLD");
17	
18	    /** Region -> inclusive 4-digit postcode range {low, high}. A region absent from this table (and
19	     *  the {@link #UNKNOWN} locality) imposes no postcode range. */
20	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
21	        "NSW", new int[] {2000, 2099},
22	        "VIC", new int[] {3000, 3099},
23	        "QLD", new int[] {4000, 4099});
24	
25	    /** The locality returned for a city absent from {@link #CITY_REGION}. */
26	    public static final String UNKNOWN = "UNKNOWN";
27	
28	    private Regions() {
29	    }
30	
31	    /**
32	     * Whether a 4-digit postcode is valid for the given city. A city whose region has no pinned
33	     * postcode range (including an unknown city) accepts any value.
34	     *
35	     * @param city     the owner's city; may be {@code null}
36	     * @param postcode the already-4-digit postcode to check
37	     * @return {@code true} when the city's region imposes no range or the postcode falls within it
38	     */
39	    public static boolean postcodeMatchesCity(String city, String postcode) {
40	        int[] range = REGION_POSTCODES.get(localityOf(city));
41	        if (range == null) {
42	            return true;
43	        }
44	        int value = Integer.parseInt(postcode);
45	        return value >= range[0] && value <= range[1];
46	    }
47	
48	    /**
49	     * Derive the locality (canonical region) preferring the postcode. The postcode's region range is
50	     * consulted first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when the postcode is absent
51	     * or falls in no known range does the city-to-region table decide. This returns the same region
52	     * for known cities but disambiguates cities that share a name.
53	     *
54	     * @param city     the owner's city; may be {@code null}
55	     * @param postcode the owner's postcode; may be {@code null}
56	     * @return the canonical region string, or {@code "UNKNOWN"} when neither postcode nor city resolves
57	     */
58	    public static String localityOf(String city, String postcode) {
59	        String byPostcode = regionOfPostcode(postcode);
60	        return byPostcode != null ? byPostcode : localityOf(city);
61	    }
62	
63	    /**
64	     * Derive the locality (canonical region) for a city.
65	     *
66	     * @param city the owner's city; may be {@code null}
67	     * @return the canonical region string, or {@code "UNKNOWN"} when the city is not in the table
68	     */
69	    public static String localityOf(String city) {
70	        return CITY_REGION.getOrDefault(city, UNKNOWN);
71	    }
72	
73	    /**
74	     * The region whose postcode range contains the given postcode, or {@code null} when the postcode
75	     * is absent, non-numeric, or falls in no known range.
76	     */
77	    private static String regionOfPostcode(String postcode) {
78	        if (postcode == null) {
79	            return null;
80	        }
81	        int value;
82	        try {
83	            value = Integer.parseInt(postcode.trim());
84	        }
85	        catch (NumberFormatException ex) {
86	            return null;
87	        }
88	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
89	            int[] range = entry.getValue();
90	            if (value >= range[0] && value <= range[1]) {
91	                return entry.getKey();
92	            }
93	        }
94	        return null;
95	    }
96	}
