1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.mapper.Regions;
9	import org.springframework.samples.petclinic.model.OwnerTelephone;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailInvalidException;
12	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsMissingException;
13	import org.springframework.samples.petclinic.rest.escalation.OwnerPostcodeInvalidException;
14	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
15	import org.springframework.web.bind.annotation.RequestBody;
16	
17	/**
18	 * First step of {@code POST /api/owners} and the single step that binds the request body. Rejects a
19	 * body that is missing or blank in any required field (firstName, lastName, address, city, telephone)
20	 * with a 400 whose {@code errors} array lists the offending field names. A whitespace-only value is
21	 * treated as blank — the DTO's {@code @Size(min = 1)} alone would accept it — so this check, not bean
22	 * validation, is the authoritative implementation of the required-field rule.
23	 *
24	 * <p>The address is normalized (see {@link OwnerAddress}) before the required-field check, so an
25	 * address that is blank once whitespace is collapsed is rejected as missing. The normalized value is
26	 * written back onto the body so the normalized, abbreviation-expanded address is what gets stored,
27	 * returned and compared for household matching.
28	 *
29	 * <p>The telephone is then converted to E.164 form (see {@link OwnerTelephone#toE164(String)}); a
30	 * value that cannot form a valid E.164 number is rejected with a 400 via
31	 * {@link OwnerTelephoneInvalidException}. The E.164 value is written back onto the body so it is what
32	 * gets stored and returned.
33	 *
34	 * <p>Email is optional. When absent (null) it is left untouched. When present it must be a
35	 * syntactically valid address; otherwise the create is rejected with a 400 via
36	 * {@link OwnerEmailInvalidException}. A valid email is lower-cased and written back onto the body so
37	 * the lower-cased value is what gets stored and returned. The validated body is republished for
38	 * {@link BuildOwner}.
39	 */
40	public class ValidateOwner {
41	
42	    /** Pragmatic syntactic check: non-empty local part, '@', non-empty domain containing a dot. */
43	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
44	
45	    /** A postcode is a string of exactly four digits. */
46	    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");
47	
48	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
49	            throws OwnerFieldsMissingException, OwnerTelephoneInvalidException,
50	            OwnerEmailInvalidException, OwnerPostcodeInvalidException {
51	        List<String> missing = new ArrayList<>();
52	        if (isBlank(request.getFirstName())) {
53	            missing.add("firstName");
54	        }
55	        if (isBlank(request.getLastName())) {
56	            missing.add("lastName");
57	        }
58	        String address = OwnerAddress.normalize(request.getAddress());
59	        if (address.isEmpty()) {
60	            missing.add("address");
61	        }
62	        if (isBlank(request.getCity())) {
63	            missing.add("city");
64	        }
65	        if (isBlank(request.getTelephone())) {
66	            missing.add("telephone");
67	        }
68	        if (!missing.isEmpty()) {
69	            throw new OwnerFieldsMissingException(missing);
70	        }
71	        request.setAddress(address);
72	        String e164 = OwnerTelephone.toE164(request.getTelephone());
73	        if (e164 == null) {
74	            throw new OwnerTelephoneInvalidException(request.getTelephone());
75	        }
76	        request.setTelephone(e164);
77	
78	        String email = request.getEmail();
79	        if (email != null) {
80	            if (!EMAIL.matcher(email).matches()) {
81	                throw new OwnerEmailInvalidException(email);
82	            }
83	            request.setEmail(email.toLowerCase());
84	        }
85	
86	        // Postcode is optional. When present it must be a 4-digit value that is valid for the
87	        // owner's city region; a city with no known region accepts any 4-digit value.
88	        String postcode = request.getPostcode();
89	        if (postcode != null) {
90	            if (!POSTCODE.matcher(postcode).matches()
91	                    || !Regions.postcodeMatchesCity(request.getCity(), postcode)) {
92	                throw new OwnerPostcodeInvalidException(postcode);
93	            }
94	        }
95	
96	        validated.set(request);
97	    }
98	
99	    private static boolean isBlank(String value) {
100	        return value == null || value.isBlank();
101	    }
102	}
