```java
private static String regionOfPostcode(String postcode) {
    if (postcode == null) {
        return null;
    }
    int value;
    try {
        value = Integer.parseInt(postcode.trim());
    }
    catch (NumberFormatException ex) {
        return null;
    }
    for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
